/// <summary>
/// Sales order load planning report dp class
/// </summary>
[SRSReportParameterAttribute(classstr(METSalesOrderLoadPlanningContract))]
class METSalesOrderLoadPlanningDP extends SrsReportDataProviderPreProcessTempDB
{
    METSalesOrderLoadPlanningLinesTmp salesOrderLoadPlanningLinesTmp;
    METSalesOrderLoadPlanningContract contract;
    RecordInsertList                  salesOrderLoadPlanningLineslist;
    SalesId                           selectedSalesId;
    SalesShippingDateConfirmed        confirmedShipDateFrom;
    SalesShippingDateRequested        confirmedShipDateTo;
    InventSiteId                      site;
    InventLocationId                  inventLocationFrom;
    LogisticsLocationRoleRecId        roleDeliveryRecId;
    custAccount                       customerAccount;
    METOrderExtractStatus             extractStatus;
    METOrderSplitGroup                orderSplitGroup;
    METSalesOrderTypeID               salesOrderTypeID;
    NoYes                             exclCreditMgmt;
    METRoute                          routeId;

}

Method.Source:
/// <summary>
/// Header tmp table
/// </summary>
/// <returns>tmp table</returns>
[SRSReportDataSetAttribute(tablestr(METSalesOrderLoadPlanningLinesTmp))]
public METSalesOrderLoadPlanningLinesTmp getHeader()
{
    select salesOrderLoadPlanningLinesTmp;
    return salesOrderLoadPlanningLinesTmp;
}

/// <summary>
///    Parses the report parameters and fills the <c>salesOrderLoadPlanningLinesTmp</c> tables with data.
/// </summary>
public void processReport()
{
    contract = this.parmDataContract() as METSalesOrderLoadPlanningContract;
    salesOrderLoadPlanningLineslist = new RecordInsertList(tableNum(METSalesOrderLoadPlanningLinesTmp), false, false, false, false, false, salesOrderLoadPlanningLinesTmp);

    str extractOrdersSelected = contract.parmSelectedRecords();
    routeId = contract.parmRouteID();
    confirmedShipDateFrom = contract.parmConfirmedShipDateFrom();
    confirmedShipDateTo = contract.parmConfirmedShipDateTo();
    customerAccount = contract.parmCustAccount();
    inventLocationFrom = contract.parmWareHouseId();
    site = contract.parmInventSiteId();
    extractStatus = contract.parmExtractStatus();
    orderSplitGroup = contract.parmOrderSplitGroup();
    salesOrderTypeID = contract.parmSalesOrderTypeID();
    exclCreditMgmt = contract.parmExclCreditMgmt();

    roleDeliveryRecId = LogisticsLocationRole::findByName(METConstants::DeliveryAddress).RecId;

    if (strLen(extractOrdersSelected) > 0)
    {
        container salesIdCon = str2con(extractOrdersSelected, ',');
        int conLen = conLen(salesIdCon);
        int counter;

        for (counter = 1; counter <= conLen; counter++)
        {
            selectedSalesId = conPeek(salesIdCon, counter);
            this.insertSalesOrders();
        }
    }
    else
    {
        this.insertSalesOrders();

    }

    salesOrderLoadPlanningLineslist.insertDatabase();
}

/// <summary>
/// insert sales orders in list
/// </summary>
public void insertSalesOrders()
{
    InventDim                   inventDim;
    InventLocation              inventLocation;
    METSalesTable               metSalesTable, metSalesTableLoc;
    SalesTable                  salesTable;
    SalesLine                   salesLine;
    ReqItemTable                reqItemTable;
    MetReqItemTable             metReqItemTable;
    CustTable                   custTable;
    DirPartyTable               dirPartyTable;
    InventDim                   inventDimReq;
    MetInventItemOrderSetup     metInventItemOrderSetup;
    boolean                     extractConfirmedOrder = WHSParameters::find().METExtractConfirmedOrders;
    NoYes                       exclCredit = exclCreditMgmt ? NoYes::No : NoYes::Yes;

    while select ItemId, InventDimId, SalesQty, SalesUnit, SalesId, LineNum, RecId from salesLine
        join CustAccount, InventSiteId, InventLocationId, SalesName, ShippingDateConfirmed, METRoute, METRouteStopNum, RecId
    from salesTable
    where salesTable.SalesId == salesLine.SalesId
        && salesTable.SalesStatus == SalesStatus::Backorder
        && (!selectedSalesId || salesLine.SalesId == selectedSalesId)
        && ((!extractConfirmedOrder || salesTable.DocumentStatus  != DocumentStatus::None)
        && salesTable.DocumentStatus != DocumentStatus::Cancelled)
        && salesTable.SalesType == SalesType::Sales
        && salesTable.METOrderExtractStatus == extractStatus
        && (!routeId  || salesTable.METRoute == routeId)
        && (salesTable.ShippingDateConfirmed >= confirmedShipDateFrom
        && salesTable.ShippingDateConfirmed <=  confirmedShipDateTo)
        && (!customerAccount || salesTable.CustAccount == customerAccount)
        && (!site || salesTable.InventSiteId  == site)
        && (!inventLocationFrom || salesTable.InventLocationId == inventLocationFrom)
        && (!salesTable.InterCompanyOriginalSalesId)
        && (!salesOrderTypeID || salesTable.METSalesOrderType == salesOrderTypeID)
        && salesTable.CredManInCreditControl == exclCredit
    join StagingLaneId, OrderSplitGroup from metSalesTableLoc
        where metSalesTableLoc.SalesTable == salesTable.RecId
         &&  metSalesTableLoc.OrderProcessingStatus == METSalesOrderProcessingStatus::OptimisationCompleted
    join Name, RecId from inventLocation
        where inventLocation.InventLocationId == salesTable.InventLocationId
    join Party from custTable
        where custTable.AccountNum == salesTable.CustAccount
    join PrimaryAddressLocation from dirPartyTable
        where dirPartyTable.RecId == custTable.Party
    join inventDim
        where inventDim.inventDimId == salesLine.InventDimId
    exists join metInventItemOrderSetup
        where metInventItemOrderSetup.ItemId == salesLine.ItemId
        && metInventItemOrderSetup.SiteId == site
    {
        salesOrderLoadPlanningLinesTmp.WareHouseName = inventLocation.Name;
        salesOrderLoadPlanningLinesTmp.Customer = salesTable.CustAccount;
        salesOrderLoadPlanningLinesTmp.CustomerName = salesTable.SalesName;
        salesOrderLoadPlanningLinesTmp.Suburb = this.getPrimaryCustDeliveryAddress(custTable.Party, dirPartyTable.PrimaryAddressLocation);            
        salesOrderLoadPlanningLinesTmp.ConfirmedShipDate = salesTable.ShippingDateConfirmed;
        salesOrderLoadPlanningLinesTmp.Route = salesTable.METRoute;
        salesOrderLoadPlanningLinesTmp.RouteStop = salesTable.METRouteStopNum;
        salesOrderLoadPlanningLinesTmp.StagingLane = metSalesTableLoc.StagingLaneId;
        salesOrderLoadPlanningLinesTmp.SalesId = salesLine.SalesId;
        salesOrderLoadPlanningLinesTmp.LineNum = salesLine.LineNum;
        salesOrderLoadPlanningLinesTmp.BrokenCase = salesLine.displayMETBrokenCase();
        salesOrderLoadPlanningLinesTmp.Cases = salesLine.displayMETCases();
        salesOrderLoadPlanningLinesTmp.TotalVolume = METWHSPhysDimUOMSite::convertVolume(salesLine.ItemId, salesLine.SalesQty, salesLine.SalesUnit, inventDim);
        salesOrderLoadPlanningLinesTmp.TotalWeight = METWHSPhysDimUOMSite::convertWeight(salesLine.ItemId, salesLine.SalesQty, salesLine.SalesUnit, inventDim);

        if (metSalesTableLoc.OrderSplitGroup == METConstants::OSCCodeP)
        {
            salesOrderLoadPlanningLinesTmp.OrderSplitGroup = METConstants::OSCCodePER;
        }
        else
        {
            salesOrderLoadPlanningLinesTmp.OrderSplitGroup = METConstants::OSCCodeDRY;
        }

        salesOrderLoadPlanningLineslist.add(salesOrderLoadPlanningLinesTmp);
    }
}

/// <summary>
/// Get WareHouse address By recevingdock role
/// </summary>
/// <param name = "_inventLocationRecId">Location RecId</param>
/// <returns>Locator</returns>
public LogisticsEntityPostalAddressView getWareHousePrimaryAddress(RefRecId _inventLocationRecId)
{
    LogisticsEntityPostalAddressView  logisticsEntityPostalAddressView;

    select firstonly Address from logisticsEntityPostalAddressView
        where logisticsEntityPostalAddressView.Entity == _inventLocationRecId
        && logisticsEntityPostalAddressView.EntityType == LogisticsLocationEntityType::Warehouse
        && logisticsEntityPostalAddressView.ValidFrom <= DateTimeUtil::getSystemDateTime()
        && logisticsEntityPostalAddressView.ValidTo >= DateTimeUtil::getSystemDateTime()
        && logisticsEntityPostalAddressView.IsPrimary == NoYes::Yes;

    return logisticsEntityPostalAddressView;
}

/// <summary>
/// Get city from customer delivery address
/// </summary>
/// <param name = "_party">Dirparty RecId</param>
/// <param name = "_primaryAddressLocation">PrimaryAddressLocation</param>
/// <returns>City Name</returns>
public LogisticsAddressCityName getPrimaryCustDeliveryAddress(RefRecId _party, LogisticsLocationRecId _primaryAddressLocation)
{
    DirPartyPostalAddressView   dirPartyPostalAddressView;
    DirPartyLocationRole        dirPartyLocationRole;

    select firstonly RecId, City from dirPartyPostalAddressView
        where dirPartyPostalAddressView.Party == _party
        && dirPartyPostalAddressView.Location == _primaryAddressLocation
        && dirPartyPostalAddressView.IsPrimary == NoYes::Yes
        && dirPartyPostalAddressView.ValidFrom <= DateTimeUtil::getSystemDateTime()
        && dirPartyPostalAddressView.ValidTo >= DateTimeUtil::getSystemDateTime()
    exists join dirPartyLocationRole
        where dirPartyLocationRole.PartyLocation == dirPartyPostalAddressView.RecId
        && dirPartyLocationRole.LocationRole == roleDeliveryRecId;

    return dirPartyPostalAddressView.City;
}
